export const machine = createMachine({
  id: 'payment', context: { balance: 10 }, initial: 'idle', states: {
    idle: { on: { START: { target: 'pending' } } },
    pending: { on: { PAY: ({ context, event }) => {
      if (event.amount <= 0) return;
      if (event.vip) return { target: 'routing' };
      if (context.balance >= event.amount) return { target: 'routing' };
      return { target: 'declined' };
    } } },
    routing: { always: { target: 'paid' } },
    paid: { type: 'final' }, declined: { type: 'final' }
  }
});

